1	/**
2	 * Spline water ribbon — the traversable stream Benny rides from the Drum A drain to the towel.
3	 *
4	 * Geometry: rows every `ds` along the master course, columns across `widthAt(s)`; a slightly
5	 * concave trough with raised frothy edges plus a short skirt under each edge (thickness).
6	 * Shader: electric-cyan core with meandering hot-pink flow bands, advected white streaks and
7	 * sparkles (two-phase flow-map advection so per-stage speeds never shear), Fresnel/haze
8	 * reflection, specular glints, cellular soap-foam fringe, Benny ripple rings + V-wake, the five
9	 * glowing chevrons on the 04 slide, a dithered hand-over to the whirlpool surface in 03 and a
10	 * drain-away for the 11 outro.
11	 */
12	import * as THREE from 'three';
13	import type { Course, StageId } from '../world/course';
14	import { FRAG_FX_GLSL, FRAG_TAIL, NOISE_GLSL, PALETTE, withFog } from './glsl';
15	
16	/** wave amplitude per stage (units); blended across boundaries */
17	const AMP: Partial<Record<StageId, number>> = {
18	  '02': 0.06, '03': 0.08, '04': 0.03, '05': 0.1, '06': 0.12, '07': 0.1, '08': 0.1, '09': 0.16, '10': 0.08, '11': 0.05,
19	};
20	export const EDGE_LIFT = 0.28;
21	
22	/**
23	 * Per-stage colour-band layout (blended across stage boundaries, baked into `aStyle`):
24	 *  x gate: 1 = pink bands taper off and part around Benny so the water at and behind him is pure
25	 *          cyan (ref 05: rows y=1200/1400 are 0% pink); 0 = bands run right past him (refs 04/06/07
26	 *          keep pink at the sides near the camera)
27	 *  y off:  band-centre offset from the meandering core centre, fraction of the half width
28	 *  z wid:  band half width, fraction of the half width
29	 * Between the two bands is the electric-cyan core; outside them more cyan, then the foam lace.
30	 */
31	type Style = [number, number, number, number];
32	/*  w free: weight of the shader's own drifting channel meander (meander() in FRAG). 0 in 05, where the
33	 *          course itself winds (S05/meander05 in course.ts) and the core is pinned to the route (see
34	 *          coreLateral) so the coins on the route stay on the cyan core. 1 elsewhere (04/06/07 unchanged).
35	 * 05 layout from ref 05 at the live 05 camera (y=600 ≈ 36 px/u, y=700 ≈ 63, y=800 ≈ 93): in the mid/far
36	 * field each pink band is ≈20 % of the water width, the cyan core ≈45 %, a thin outer cyan strip ≈7 %
37	 * → band centre 0.62 hw, half width 0.19 hw. Toward Benny the bands taper to half width (gate, FRAG),
38	 * which gives the ref's ≈100–130 px bands at y=800 and a pure-cyan near field. */
39	const BAND_STYLE: Partial<Record<StageId, Style>> = {
40	  '04': [0, 0.6, 0.19, 1],
41	  '05': [1, 0.62, 0.19, 0],
42	  '06': [0.4, 0.48, 0.1, 1],
43	  '07': [0, 0.52, 0.13, 1],
44	};
45	const BAND_DEFAULT: Style = [0, 0.5, 0.12, 1];
46	
47	function bandStyleAt(course: Course, s: number): Style {
48	  const o: Style = [0, 0, 0, 0];
49	  let w = 0;
50	  for (const st of course.stages) {
51	    const a = smooth(st.s0 - 5, st.s0 + 5, s) * (1 - smooth(st.s1 - 5, st.s1 + 5, s));
52	    if (a <= 0) continue;
53	    const v = BAND_STYLE[st.id] ?? BAND_DEFAULT;
54	    for (let i = 0; i < 4; i++) o[i] += v[i] * a;
55	    w += a;
56	  }
57	  if (w <= 0) return [...(BAND_STYLE[course.stageAtS(s).id] ?? BAND_DEFAULT)];
58	  return [o[0] / w, o[1] / w, o[2] / w, o[3] / w];
59	}
60	
61	/**
62	 * 05 current: lateral position (units, ribbon `right` axis, + = right) of the centre of the
63	 * electric-cyan core relative to the route centreline. The core swings WITH the course meander,
64	 * amplified by CORE_SWING, so the two pink bands trace S-bends ≈(1 + CORE_SWING)× as strong as the
65	 * route's own (ref 05: ±60–120 px). Bounded by CORE_SWING · max|offset05| (≈0.9 · 1.85 = 1.7 u at the
66	 * far crest; ≤1.25 u within 35 u of the 05 checkpoint), inside the ≥2 u core half width, so a coin on
67	 * the route centre (lat 0) still sits on cyan. 0 outside 05.
68	 * gameplay/coins.ts may place the 05 coins at this lateral to put them exactly on the core centre.
69	 */
70	export const CORE_SWING = 0.9;
71	export function coreLateral(course: Course, s: number): number {
72	  const st = course.stage('05');
73	  if (s <= st.s0 || s >= st.s1) return 0;
74	  return CORE_SWING * course.offset05(s) * course.sample(s).right.x;
75	}
76	
77	/**
78	 * Ribbon colours in shader (pre-tonemap, linear) space. NeutralToneMapping desaturates anything
79	 * whose peak channel passes ≈0.76·exposure, so these were solved by inverting Neutral at the game's
80	 * exposure 0.86 (src/render/env.ts). Flat values after tone mapping: cyanDeep #0065D6, cyan #1D89F0,
81	 * cyanBright #42C8F7, pinkDeep #E206BE, pink #F741DD (H 308°, not violet), pinkLight #FA93E7. The
82	 * streaks/crests/glints added on top lift the rendered cyan median to ≈#06A7FF (ref 05 #039FF6).
83	 * Crests/highlights are allowed to desaturate toward white (that is how the ref highlights look).
84	 * The shared PALETTE in glsl.ts is untouched (whirlpool, drum and final wave use it).
85	 */
86	const lin = (r: number, g: number, b: number) => new THREE.Color().setRGB(r, g, b, THREE.LinearSRGBColorSpace);
87	const RIBBON_PAL = {
88	  cyanDeep: lin(0.0, 0.15, 0.78),
89	  cyan: lin(0.0, 0.31, 1.12),
90	  cyanBright: lin(0.04, 0.95, 1.55),
91	  pinkDeep: lin(0.9, 0.02, 0.62),
92	  pink: lin(1.55, 0.03, 1.2),
93	  pinkLight: lin(2.2, 0.5, 1.8),
94	};
95	/**
96	 * 05 river palette (wave 4), shader-space linear values solved through the full post chain
97	 * (exposure 0.86 → Neutral → sRGB → grade.ts saturation 1.36 / contrast 1.15; bloom ignored) so the
98	 * flat colours land on the ref 05 samples instead of clipping: cyan deep ≈#0466CF (troughs),
99	 * cyan ≈#029AF3 (ref core), bright ≈#33C0FF, streak ≈#8FE6FF; pink deep ≈#BC16A8, pink ≈#F73DEA
100	 * (ref #F739E5 / band medians #F749F1), light ≈#FA9EF2, streak ≈#FEC0F6. The old RIBBON_PAL pink
101	 * (1.55, 0.03, 1.2) clips to #FF23FF in that chain and the lighting lifted it to lavender #FF6CFF.
102	 */
103	const RIVER05_PAL = {
104	  cyanDeep: lin(0.04, 0.16, 0.46),
105	  cyan: lin(0.06, 0.37, 0.74),
106	  cyanBright: lin(0.1, 0.8, 1.8),
107	  cyanStreak: lin(0.36, 1.25, 2.1),
108	  pinkDeep: lin(0.36, 0.04, 0.3),
109	  pink: lin(0.7, 0.08, 0.64),
110	  pinkLight: lin(0.92, 0.3, 0.88),
111	  pinkStreak: lin(1.1, 0.58, 1.04),
112	};
113	/** 05 texture advection relative to the stage speed (>1: the current visibly overtakes Benny) */
114	const FLOW05 = 1.3;
115	
116	export function ampAt(course: Course, s: number): number {
117	  let v = 0, w = 0;
118	  for (const st of course.stages) {
119	    const a = smooth(st.s0 - 5, st.s0 + 5, s) * (1 - smooth(st.s1 - 5, st.s1 + 5, s));
120	    if (a > 0) { v += (AMP[st.id] ?? 0.08) * a; w += a; }
121	  }
122	  let amp = w > 0 ? v / w : 0.08;
123	  // calm the long straight of the deep plunge (fast sheet flow)
124	  const pt = course.marks['07_plunge_top'], pb = course.marks['07_plunge_bottom'];
125	  if (pt !== undefined) amp *= 1 - 0.6 * smooth(pt, pt + 8, s) * (1 - smooth(pb - 8, pb, s));
126	  return amp;
127	}
128	
129	function smooth(a: number, b: number, x: number) {
130	  const t = Math.min(1, Math.max(0, (x - a) / (b - a)));
131	  return t * t * (3 - 2 * t);
132	}
133	
134	/** CPU mirror of the vertex displacement (keep in sync with VERT). */
135	export function ribbonWave(u: number, s: number, t: number, amp: number): number {
136	  const au = Math.min(1, Math.abs(u));
137	  const trough = EDGE_LIFT * au * au * au;
138	  return trough + amp * (0.6 * Math.sin(s * 0.9 - t * 2.4 + u * 1.7) + 0.4 * Math.sin(s * 0.41 + t * 1.5 - u * 2.3));
139	}
140	
141	const VERT = /* glsl */ `
142	attribute vec2 aUV;      // x = u (-1..1 across), y = s (arc length)
143	attribute float aHalfW;
144	attribute float aSpeed;
145	attribute float aAmp;
146	attribute float aSkirt;  // 0 surface, 1 skirt bottom
147	attribute vec4 aStyle;   // band layout: gate, offset, half width, free-meander weight (see BAND_STYLE)
148	attribute float aCore;   // 05: core-centre lateral swing (units, see coreLateral)
149	attribute vec3 aTan;     // course tangent (downstream)
150	uniform float uTime;
151	uniform vec4 uHide;      // s03Start, s04Start, chuteMark, unused
152	varying vec2 vUV;
153	varying float vHalfW;
154	varying float vSpeed;
155	varying float vSkirt;
156	varying float vHide;
157	varying vec4 vStyle;
158	varying float vCore;
159	varying vec3 vTanW;
160	varying vec3 vPosW;
161	varying vec3 vNormalW;
162	#include <fog_pars_vertex>
163	void main() {
164	  vStyle = aStyle;
165	  vCore = aCore;
166	  vTanW = normalize(mat3(modelMatrix) * aTan);
167	  float u = aUV.x;
168	  float s = aUV.y;
169	  float h = aAmp * (0.6 * sin(s * 0.9 - uTime * 2.4 + u * 1.7) + 0.4 * sin(s * 0.41 + uTime * 1.5 - u * 2.3));
170	  vec3 p = position + normal * h * (1.0 - aSkirt);
171	  vec4 wp = modelMatrix * vec4(p, 1.0);
172	  vPosW = wp.xyz;
173	  vNormalW = normalize(mat3(modelMatrix) * normal);
174	  vUV = aUV;
175	  vHalfW = aHalfW;
176	  vSpeed = aSpeed;
177	  vSkirt = aSkirt;
178	  // hand the stream over to the whirlpool surface during 03 (dithered fade both ways)
179	  float inside03 = smoothstep(uHide.x + 0.5, uHide.x + 3.5, s) * (1.0 - smoothstep(uHide.y - 9.0, uHide.y - 1.5, s));
180	  vHide = 1.0 - inside03;
181	  vec4 mvPosition = viewMatrix * wp;
182	  gl_Position = projectionMatrix * mvPosition;
183	  #include <fog_vertex>
184	}
185	`;
186	
187	const FRAG = /* glsl */ `
188	uniform float uTime;
189	uniform vec3 uCyanDeep;
190	uniform vec3 uCyan;
191	uniform vec3 uCyanBright;
192	uniform vec3 uPinkDeep;
193	uniform vec3 uPink;
194	uniform vec3 uPinkLight;
195	uniform vec3 uFoam;
196	uniform vec3 uFoamLav;
197	uniform vec3 uHaze;
198	uniform vec3 uLightDir;
199	uniform vec3 uBenny;      // s, lateral (units), strength
200	uniform float uBennyR;    // Benny's waterline radius (units)
201	uniform vec3 uChevron;    // start s, spacing, enabled
202	uniform vec2 uOutro;      // amount, chamber start s
203	// 05 river palette (see RIVER05_PAL) + its one constant advection speed (no stage-speed shear)
204	uniform vec3 uC5Deep;
205	uniform vec3 uC5;
206	uniform vec3 uC5Bright;
207	uniform vec3 uC5Streak;
208	uniform vec3 uP5Deep;
209	uniform vec3 uP5;
210	uniform vec3 uP5Light;
211	uniform vec3 uP5Streak;
212	uniform float uFlow05;
213	varying vec2 vUV;
214	varying float vHalfW;
215	varying float vSpeed;
216	varying float vSkirt;
217	varying float vHide;
218	varying vec4 vStyle;
219	varying float vCore;
220	varying vec3 vTanW;
221	varying vec3 vPosW;
222	varying vec3 vNormalW;
223	#include <fog_pars_fragment>
224	${NOISE_GLSL}
225	${FRAG_FX_GLSL}
226	
227	// Stationary channel shape (refs 05–07): lateral offset (units) of the electric-cyan core centre
228	// relative to the course centreline. Two incommensurate sines + slow noise so the S-curves do not
229	// visibly repeat; λ≈26 u differs from the course's own 05 geometry meander (λ≈36 u), so the two beat
230	// rather than cancel. It only drifts slowly downstream (+s) at a constant rate (no shear between
231	// stage speeds); the strand texture below is what is advected at the local stage speed.
232	float meander(float s, float hw) {
233	  float a = s - uTime * 0.7;
234	  float m = 0.2 * sin(a * 0.24) + 0.08 * sin(a * 0.53 + 1.3) + 0.12 * (vnoise(vec2(a * 0.05, 4.7)) - 0.5);
235	  return m * min(hw, 4.5);
236	}
237	
238	// polynomial smooth minimum (k = blend width, units)
239	float smin(float a, float b, float k) {
240	  float h = max(k - abs(a - b), 0.0) / k;
241	  return min(a, b) - h * h * k * 0.25;
242	}
243	
244	// Combed flow lines (ref 05: thin bright streaks along the flow, 2–4 px apart in the mid-ground).
245	// Anti-aliased lines across the flow (K slots per unit), each broken into tapered streak segments of
246	// varying length/brightness. Line width is in PIXELS (≈1.2 px core + ≈2.5 px glow), so near the camera
247	// the slots spread apart into sparse crisp glints instead of wide parallel light stripes (the
248	// "flattened stripes" the user rejected); the lines fade once they get closer than ≈3 px.
249	float combed(float x, float v, float K, float seed) {
250	  float p = x * K;
251	  float id = floor(p);
252	  float fw = max(fwidth(p), 1e-4);            // slots per pixel
253	  float hs = hash12(vec2(id, seed));
254	  float dpx = abs(fract(p) - 0.5 - (hs - 0.5) * 0.5) / fw;   // pixels from the line centre
255	  float line = (1.0 - smoothstep(0.4, 1.3, dpx)) * 0.8 + exp(-dpx * 0.45) * 0.3;
256	  // each line breaks into tapered streak segments; sparser when the slots are far apart on screen
257	  float sparse = smoothstep(0.03, 0.006, fw);
258	  float seg = smoothstep(0.5 + 0.15 * sparse, 0.9, vnoise(vec2(id * 3.7 + seed, v * 0.2 + hs * 9.0)));
259	  return line * seg * (0.45 + 0.55 * hs) * (1.0 - smoothstep(0.22, 0.4, fw));
260	}
261	
262	// advected strand texture ("combed" glossy water lines parallel to the flow)
263	// x = lateral units relative to the meander centre, v = advected arc length, aa = 0..1 detail fade
264	// returns: x = height 0..1 (shading + bump), y = white glint lines, z = mid strands, w = fine strands
265	// sw = swirl (05): the strands wander laterally and are less stretched, so the water reads as
266	// curling glossy flow instead of uniform straight parallel stripes (the user's rejected look)
267	vec4 strands(float x, float v, vec2 aa, float sw) {
268	  x += sw * 0.9 * (vnoise(vec2(x * 0.45, v * 0.2 + 7.0)) - 0.5);
269	  float a = vnoise(vec2(x * 2.4, v * (0.08 + 0.1 * sw)));
270	  float b = vnoise(vec2(x * 7.0 + a * 1.6, v * 0.19 + 5.0));
271	  #ifdef LOW_Q
272	  float c = b;
273	  #else
274	  float c = vnoise(vec2(x * 17.0 + b * 2.2, v * 0.42 + 3.0));
275	  #endif
276	  b = mix(0.5, b, aa.x);
277	  c = mix(0.5, c, aa.y);
278	  float h = a * 0.42 + b * 0.34 + c * 0.24;
279	  h = smoothstep(0.18, 0.82, h);              // more contrast: deep azure troughs, bright crests
280	  float line = smoothstep(0.72, 0.86, c) * aa.y + smoothstep(0.7, 0.86, b) * aa.x * 0.85;
281	  // the combed lines follow the large-scale strand warp so they bend with the flow
282	  float xw = x + (a - 0.5) * 0.5;
283	  line = max(line, combed(xw, v, 6.0, 0.0) * 0.85);
284	  #ifndef LOW_Q
285	  line = max(line, combed(xw + (b - 0.5) * 0.12, v * 1.3, 15.0, 11.0) * 0.55);
286	  #endif
287	  return vec4(h, line, b, c);
288	}
289	
290	// 05 silk streaks: anti-aliased light lines along the FLOW coordinate q (band-relative, so they bend
291	// with the pink S-bands instead of running as straight parallel road stripes). Each line wanders
292	// slowly (wig, slot fraction) so neighbours braid, and breaks into advected tapered segments of
293	// varying brightness. Width in pixels; the lines fade once they crowd closer than ≈3 px.
294	float silk(float q, float v, float K, float seed, float wig) {
295	  float p = q * K;
296	  float fw = max(fwidth(p), 1e-4);
297	  float id = floor(p);
298	  float hs = hash12(vec2(id, seed));
299	  float c = 0.5 + (hs - 0.5) * 0.34 + wig * sin(v * (0.28 + 0.3 * hs) + hs * 6.283);
300	  float dpx = abs(fract(p) - c) / fw;
301	  float line = (1.0 - smoothstep(0.3, 1.2, dpx)) * 0.7 + exp(-dpx * 0.55) * 0.4;
302	  // short tapered brush dashes (≈1–2 u: ref 05 speed streaks are 30–80 px in the mid field)
303	  float n = vnoise(vec2(id * 3.1 + seed, v * 0.42 + hs * 17.0));
304	  float seg = smoothstep(0.5, 0.86, n);
305	  return line * seg * (0.5 + 0.7 * hs) * (1.0 - smoothstep(0.22, 0.42, fw));
306	}
307	
308	void main() {
309	  float u = vUV.x;
310	  float s = vUV.y;
311	  // dithered hide (03 hand-over)
312	  if (vHide < 0.5) discard;
313	  float cutFoam = 1.0 - smoothstep(0.5, 0.85, vHide);
314	  // 11 outro: the stream drains away in the chamber, leaving puddles
315	  if (uOutro.x > 0.0 && s > uOutro.y - 2.0) {
316	    float n = vnoise(vec2(u * 3.0, s * 0.35)) * 0.7 + 0.3;
317	    if (n < uOutro.x * 1.15) discard;
318	  }
319	
320	  // ---- channel layout: winding cyan core between two hot-pink S-bands, cyan again outside ----
321	  float hw = vHalfW;
322	  float lat = u * hw;                         // lateral units in the ribbon frame
323	  // core centre: free drifting meander on 04/06/07 (freeK = 1); on 05 (freeK = 0) pinned to the
324	  // course's own S-meander, amplified (vCore = CORE_SWING · offset05), so the coins stay on cyan
325	  float freeK = vStyle.w;
326	  float sw = 1.0 - freeK;                     // weight of the 05 river look (1 on 05 only)
327	  float M = meander(s, hw) * freeK + vCore;
328	  float x = lat - M;                          // lateral units in the core's frame
329	  // 05: the pink bands swing a further ±1.05 u about the core (a stationary λ≈20 u S on top of the
330	  // course meander, in phase with it: left at s≈139.5 / y≈800, right at s≈149.7 / y≈680 on the locked
331	  // view), so they read as ≈2 clear S-bends to the VP (ref 05: ±100 px). A small 2nd harmonic skews
332	  // each bend so the S is not a plain sine. The coins (at coreLateral = M) stay ≥0.3 u inside the cyan.
333	  float sbend = sw * (1.05 * sin(s * 0.31 - 0.834) + 0.18 * sin(s * 0.62 + 0.6));
334	  float xb = x - sbend;                       // band frame (== x on 04/06/07)
335	
336	  // detail fade with distance (cells per pixel), keeps far water from shimmering
337	  float fwx = fwidth(x);
338	  float fws = fwidth(s);
339	  // (a noise cell must stay ≳6–8 px wide; the combed lines of ref 05 are 2–4 px apart in the
340	  // mid-ground, so fading earlier than this flattens the water into a plain fill)
341	  vec2 aa = vec2(1.0 - smoothstep(0.12, 0.26, max(fwx * 7.0, fws * 0.19)),
342	                 1.0 - smoothstep(0.09, 0.2, max(fwx * 17.0, fws * 0.42)));
343	  // hair-fine combed strands for close-up water (refs: dense parallel flow lines)
344	  float aaH = 1.0 - smoothstep(0.14, 0.3, fwx * 46.0);
345	  #ifdef LOW_Q
346	  aa.y = 0.0;
347	  aaH = 0.0;
348	  #endif
349	
350	  // two-phase flow-map advection of the strands (period 4 s; offset scales with stage speed)
351	  float ph0 = fract(uTime * 0.25);
352	  float ph1 = fract(uTime * 0.25 + 0.5);
353	  float w0 = 1.0 - abs(1.0 - 2.0 * ph0);
354	  // (04/06/07 strand texture; 05 has its own silk/swell field below)
355	  vec4 F = vec4(0.5, 0.0, 0.5, 0.5);
356	  if (freeK > 0.001) F = mix(strands(x, s - vSpeed * ph1 * 4.0 + 23.0, aa, sw), strands(x, s - vSpeed * ph0 * 4.0, aa, sw), w0);
357	  float v5 = s - uTime * uFlow05;             // 05 advected arc length (one constant speed: no shear)
358	
359	  // Benny parts the bands like a bow wave (vStyle.x, ref 05): just ahead of him they narrow and
360	  // swing outward, so the water at and behind him (the near field) is pure cyan; behind him they
361	  // continue only as thin streaks pushed out toward the foam banks
362	  // (05: the near rows only show lat ±2.3 behind Benny, so a light parting is enough there)
363	  float gate = 1.0, part = 0.0, near05 = 1.0;
364	  float db = s - uBenny.x;
365	  if (vStyle.x > 0.0) {
366	    // 05 (wave 4): the bands stay wide (≥75 %) and run in CLOSER (0.8× offset) beside Benny, so they
367	    // sweep past both his sides like ref 05 (pink beside the hat/body at y≈800–1000) instead of
368	    // parting out under the foam banks; full width/offset ≈14–20 u ahead
369	    float g05 = 0.75 + 0.25 * smoothstep(1.0, 20.0, db);
370	    float gOld = 0.4 + 0.6 * smoothstep(0.0, 4.5, db);
371	    gate = mix(1.0, mix(g05, gOld, freeK), vStyle.x);
372	    part = vStyle.x * hw * 0.3 * freeK * (1.0 - smoothstep(-1.0, 9.0, db));
373	    near05 = mix(1.0, 0.8 + 0.2 * smoothstep(2.0, 14.0, db), sw * vStyle.x);
374	  }
375	  float hwc = min(hw, 4.5);
376	  float aaw = fwidth(lat) * 0.85 + 0.01;      // ≈1 px edges: no lavender cyan/pink blend zone
377	  // flowing band edges (the advected strand texture). 05: only a soft travelling ripple, so the band
378	  // edges are clean S-curves instead of the torn/jagged combed edges of the old slab
379	  float pert = mix((vnoise(vec2(x * 0.9, v5 * 0.12 + 3.0)) - 0.5) * 0.3,
380	                   (F.z - 0.5) * 0.5 + (F.w - 0.5) * 0.22, freeK) * hwc * 0.22;
381	  // 05: the band shapes are carried downstream (a slow travelling wobble), so the pink S-sections
