import sys, json
import numpy as np
from PIL import Image
from scipy import ndimage

def load(p):
    im = Image.open(p).convert('RGB')
    if im.size != (864, 1536): im = im.resize((864, 1536), Image.LANCZOS)
    return np.asarray(im).astype(np.int32)

def pinkmask(a):
    r, g, b = a[..., 0], a[..., 1], a[..., 2]
    return (r > 170) & (b > 140) & (g < 150) & (r - g > 70)

def cyanmask(a):
    r, g, b = a[..., 0], a[..., 1], a[..., 2]
    return (b > 170) & (r < 130) & (g > 90)

def runs(row, minlen=8):
    out = []; start = None
    for x, v in enumerate(list(row) + [False]):
        if v and start is None: start = x
        if not v and start is not None:
            if x - start >= minlen: out.append((start, x - 1))
            start = None
    return out

def report(p):
    a = load(p)
    pm = pinkmask(a)
    # smooth pink mask horizontally to bridge small streak gaps
    pms = ndimage.binary_closing(pm, structure=np.ones((3, 9)))
    res = {}
    rows = {}
    for y in [600, 650, 700, 750, 800, 850, 900, 950, 1000, 1100, 1200, 1250, 1300, 1350, 1400, 1450, 1500]:
        rows[y] = runs(pms[y], 8)
    res['pink_runs'] = rows
    # near field stats x150-700 y1250-1536
    nf = a[1250:1536, 150:700]
    lum = nf.mean(axis=2)
    res['near_lum'] = dict(std=round(float(lum.std()), 1), p5=round(float(np.percentile(lum, 5)), 1), p95=round(float(np.percentile(lum, 95)), 1))
    # pink fraction in near field and behind Benny
    res['near_pink_pct'] = round(100 * float(pm[1000:1536].mean()), 1)
    res['behind_pink_pct'] = round(100 * float(pm[1200:1360, 245:600].mean()), 1)
    # cyan medians
    for y in [1300, 1400, 1500]:
        row = a[y - 5:y + 5].reshape(-1, 3)
        cm = cyanmask(row[None])[0]
        if cm.sum():
            med = np.median(row[cm], axis=0).astype(int)
            res[f'cyan_med_{y}'] = '#%02X%02X%02X' % tuple(med)
    # white glint blobs: small bright near-white components
    wh = (a.min(axis=2) > 225)
    lab, n = ndimage.label(wh)
    sizes = ndimage.sum(wh, lab, range(1, n + 1))
    coms = ndimage.center_of_mass(wh, lab, range(1, n + 1))
    near = sum(1 for s_, c in zip(sizes, coms) if 2 <= s_ <= 200 and c[0] >= 1200)
    mid = sum(1 for s_, c in zip(sizes, coms) if 2 <= s_ <= 200 and 700 <= c[0] < 1200)
    res['glints_near_mid'] = (near, mid)
    # whiteness fraction in near field (x 0-864, y1000-1536)
    res['white_pct_near'] = round(100 * float(wh[1000:1536].mean()), 2)
    # cyan fraction in near field
    res['cyan_pct_near'] = round(100 * float(cyanmask(a)[1000:1536].mean()), 1)
    res['cyan_pct_mid'] = round(100 * float(cyanmask(a)[560:1000].mean()), 1)
    res['pink_pct_mid'] = round(100 * float(pm[560:1000].mean()), 1)
    return res

for p in sys.argv[1:]:
    r = report(p)
    print('==', p)
    for k, v in r.items():
        if k == 'pink_runs':
            for y, rr in v.items(): print(f'  y{y}: {rr}')
        else:
            print(' ', k, v)
